function __bwUnarySubtract(value: any): number { return -value }
function __bwCompareStrictNotEqual(left: any, right: any): boolean { return left !== right }
function __bwCompareStrictEqual(left: any, right: any): boolean { return left === right }
function __bwCompareLess(left: any, right: any): boolean { return left < right }
function __bwCompareGreater(left: any, right: any): boolean { return left > right }
function __bwCompareLessEqual(left: any, right: any): boolean { return left <= right }
function __bwStartup () {
    let __bwValue1: boolean = false
    let __bwValue2: boolean = false
    let __bwValue3: boolean = false
    let __bwValue4: boolean = false
    let __bwValue5: boolean = false
