    blue = image.create(2, 2)
    blue.fill(9)
    horizontal = null
    horizontal = sprites.create(yellow, SpriteKind.Player)
    vertical = null
    vertical = sprites.create(blue, SpriteKind.Food)
    horizontal.setPosition(40, 40)
    vertical.setPosition(110, 90)
    horizontal.fx = 200
    vertical.fy = 200
    horizontal.vx = 100
    vertical.vy = __bwUnarySubtract((0 + 100))
    __bwValue1 = __bwCompareStrictNotEqual(horizontal.vx, (0 + 0))
    if (__bwCompareStrictEqual(!!(__bwValue1), __bwCompareLess(1, 0))) {
        __bwValue1 = __bwCompareStrictNotEqual(vertical.vy, (0 + 0))
    }
    while (!(!!!(__bwValue1))) {
        pause(0.005 * 1000)
        __bwValue1 = __bwCompareStrictNotEqual(horizontal.vx, (0 + 0))
        if (__bwCompareStrictEqual(!!(__bwValue1), __bwCompareLess(1, 0))) {
            __bwValue1 = __bwCompareStrictNotEqual(vertical.vy, (0 + 0))
        }
        pause(20)
    }
    horizontalStopped = __bwCompareStrictEqual(horizontal.vx, (0 + 0))
    verticalStopped = __bwCompareStrictEqual(vertical.vy, (0 + 0))
    __bwValue2 = __bwCompareGreater(horizontal.x, (0 + 40))
    if (!!(__bwValue2)) {
        __bwValue2 = __bwCompareLess(horizontal.x, (0 + 70))
    }
    horizontalMoved = __bwValue2
    __bwValue3 = __bwCompareLess(vertical.y, (0 + 90))
    if (!!(__bwValue3)) {
        __bwValue3 = __bwCompareGreater(vertical.y, (0 + 60))
    }
    verticalMoved = __bwValue3
    horizontal.ax = 100
    while (!(!__bwCompareLessEqual(horizontal.vx, (0 + 0)))) {
        pause(0.005 * 1000)
        pause(20)
    }
    accelerationOverridesFriction = __bwCompareGreater(horizontal.vx, (0 + 0))
    horizontal.ax = 0
    while (!(!__bwCompareStrictNotEqual(horizontal.vx, (0 + 0)))) {
        pause(0.005 * 1000)
        pause(20)
    }
    horizontalFriction = horizontal.fx
    verticalFriction = vertical.fy
    __bwValue4 = horizontalStopped
    if (!!(__bwValue4)) {
        __bwValue4 = verticalStopped
    }
    __bwValue5 = __bwValue4
    if (!!(__bwValue5)) {
        __bwValue5 = horizontalMoved
    }
    __bwValue6 = __bwValue5
    if (!!(__bwValue6)) {
        __bwValue6 = verticalMoved
    }
    __bwValue7 = __bwValue6
    if (!!(__bwValue7)) {
        __bwValue7 = accelerationOverridesFriction
    }
    __bwValue8 = __bwValue7
    if (!!(__bwValue8)) {
        __bwValue8 = __bwCompareStrictEqual(horizontalFriction, (0 + 200))
    }
    __bwValue9 = __bwValue8
    if (!!(__bwValue9)) {
        __bwValue9 = __bwCompareStrictEqual(verticalFriction, (0 + 200))
    }
    frictionMotionDone = __bwValue9
}
