function Game_fib (n: number): number {
    if ((n < 2)) {
        return n
    }
    return (Game_fib((n - 1)) + Game_fib((n - 2)))
}
function Game_even (n: number): number {
    if (((n as any) == 0)) {
        return (0 + 1)
    }
    return Game_odd((n - 1))
}
function Game_odd (n: number): number {
    if (((n as any) == 0)) {
